import {destinations,destinationOf,riverStops,overviewStops} from './story-data.mjs?v=3.3';
import {clamp,ease,mix,pathMetric,samplePath,nearestPosition,buildSchedule,stateAt,headingAt,shortestAngle} from './story-engine.mjs?v=3.3';
const $=id=>document.getElementById(id);
const state={mode:'explore',destination:'all',river:null,time:0,playing:false,schedule:null,metric:null,chapterKey:'',free:false,activityPaused:false,speed:1,reading:false};
let guide,local,view,routes=[],branches={},meta,routeBounds,lastTime=0,overviewLines=[];
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function makeRiverChapters(route){
 const metric=pathMetric(route.path),given=[...(riverStops[route.id]||[])];
 if(!given.some(x=>x.at===0))given.unshift({at:0,short:'Headwaters',title:route.source,kind:'WHERE THE JOURNEY BEGINS',text:`Descend toward the mapped beginning of the ${route.name}. ${route.source.includes('confluence')?'This river begins where two streams meet.':'The source marker locates the headwater region at this map’s scale.'}`,distance:3.5,bearing:.8});
 if(given.length===1)given.push({at:.48,short:'Downstream',title:route.id==='luni'?'Across an arid landscape':`Following the ${route.name}`,kind:'THE RIVER IN ITS LANDSCAPE',text:route.description,distance:4});
 if(!given.some(x=>x.at===1))given.push({at:1,short:'Outlet',title:route.id==='luni'?'Toward the Rann':`Toward the ${destinationOf(route)==='arabian'?'Arabian Sea':'Bay of Bengal'}`,kind:'MAPPED OUTLET',text:route.id==='luni'?'The Luni reaches the arid Rann drainage region. A mapped channel is not evidence of year-round flow. Pull back to see the route from its separate headwaters.':`${['yamuna','beas','sutlej'].includes(route.id)?'The water has continued through the receiving river system. ':''}This channel ends at the dataset’s coastal or estuary limit. The wider destination is the ${destinationOf(route)==='arabian'?'Arabian Sea':'Bay of Bengal'}. The view now widens to reveal the journey.`,distance:6.8,bearing:.2});
 const stops=given.map(s=>({...s,...nearestPosition(route,metric,s.branch&&branches[s.branch]?branches[s.branch].join:s.at)})).filter(s=>s.errorKm<28).sort((a,b)=>a.t-b.t);
 for(const stop of stops){if(stop.scene){const shot=sceneDefinitions[stop.scene].shots[0];stop.bearing=headingAt(metric,stop.t)+Math.atan2(shot.position[0]-shot.target[0],shot.position[2]-shot.target[2]);}}
 if(stops.length<3)stops.splice(1,0,{t:.45,short:'Downstream',title:`Along the ${route.name}`,kind:'MIDDLE COURSE',text:route.description,distance:4});
 const xs=route.path.map(p=>p[0]),zs=route.path.map(p=>p[2]);routeBounds={center:[(Math.min(...xs)+Math.max(...xs))/2,0,(Math.min(...zs)+Math.max(...zs))/2],distance:Math.max(5,Math.max(Math.max(...xs)-Math.min(...xs),Math.max(...zs)-Math.min(...zs))*.95)};routeBounds.center[1]=view.heightAt(routeBounds.center[0],routeBounds.center[2]);
 return{metric,schedule:buildSchedule(stops)};
}
function matches(route,group){return group==='all'||(group==='himalaya'?route.family==='Himalayan':group==='peninsula'?route.family!=='Himalayan'&&route.id!=='luni':destinationOf(route)===group);}
function overviewHighlight(group){view.group('overview').visible=true;for(const e of overviewLines){const active=matches(e.route,group);e.mesh.material.opacity=active?.85:.06;for(const a of e.arrows)a.visible=active;}view.clearLabels('active');
 const examples={all:['ganga','brahmaputra','indus','godavari','narmada','kaveri'],himalaya:['ganga','brahmaputra','indus'],peninsula:['godavari','krishna','kaveri','narmada'],bay:['ganga','brahmaputra','godavari','krishna','kaveri'],arabian:['indus','narmada','tapi','periyar'],inland:['luni']}[group]||[];
 for(const id of examples){const r=routes.find(x=>x.id===id),m=pathMetric(r.path);view.addLabel(r.name,samplePath(m,.42).point,'river','active');if(group==='himalaya'||group==='peninsula')view.addLabel('Source · '+r.name,r.path[0],'source','active');}
 if(group==='bay'||group==='all')view.addLabel('BAY OF BENGAL',view.geo(88,15),'sea','active');if(group==='arabian'||group==='all')view.addLabel('ARABIAN SEA',view.geo(68.5,17),'sea','active');if(group==='inland')view.addLabel('RANN OF KACHCHH',view.geo(70,23.8),'sea','active');
}
function populateRivers(){const select=$('river');select.replaceChildren(new Option('Choose a river…',''));for(const [key,d] of Object.entries(destinations)){if(key==='all'||state.destination!=='all'&&state.destination!==key)continue;const group=document.createElement('optgroup');group.label=d.name;for(const r of routes.filter(r=>destinationOf(r)===key))group.append(new Option(r.name,r.id));select.append(group);}}
function showExplorer(destination='all'){guide?.reset();local?.reset();state.mode='explore';state.destination=destination;state.river=null;state.schedule=null;state.playing=false;state.free=false;state.chapterKey='';document.body.className='';$('cinema').hidden=true;$('intro').hidden=false;$('panel').hidden=false;$('destination-text').textContent=destinations[destination].text;document.querySelectorAll('[data-destination]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.destination===destination)));populateRivers();view.clear('route');view.clear('branch');view.reveal=null;view.glow=null;view.branchReveal=null;view.marker.visible=false;view.ring.visible=false;view.networks.forEach((n,i)=>n.material.opacity=[.15,.30,.6][i]);overviewHighlight(destination);const shot=overviewStops.find(s=>s.group===destination)||overviewStops[0];view.flyTo(view.shot(view.geo(...shot.center),shot.distance,shot.bearing),2.8);$('resume-camera').hidden=true;}
function enterCinema(mode){guide?.reset();local?.reset();state.activityPaused=false;state.mode=mode;state.free=false;state.chapterKey='';state.time=0;state.playing=false;document.body.className='cinematic';$('intro').hidden=true;$('panel').hidden=true;$('cinema').hidden=false;$('resume-camera').hidden=true;$('next-journeys').hidden=true;view.guided=true;view.networks.forEach((n,i)=>n.material.opacity=[.08,.14,.30][i]);}
function enterOverview(play=true){enterCinema('overview');state.river=null;state.metric=null;state.schedule=buildSchedule(overviewStops,true);view.clear('route');view.clear('branch');view.reveal=null;view.glow=null;view.branchReveal=null;view.marker.visible=false;view.ring.visible=false;$('tour-title').textContent='How India’s rivers flow';$('tour-subtitle').textContent='Source regions → connected rivers → destinations';populateChapters();setTime(0);view.flyTo(poseAt(stateAt(state.schedule,0)),2.8);state.playing=play&&!reduced;syncPlay();}
function enterRiver(id,play=false){const route=routes.find(r=>r.id===id);if(!route)throw new Error('Choose a river from the atlas.');enterCinema('river');state.river=route;state.destination=destinationOf(route);const prepared=makeRiverChapters(route);state.metric=prepared.metric;state.schedule=prepared.schedule;local.setRoute(route,prepared.schedule.chapters);view.group('overview').visible=false;view.showRoute(route);$('tour-title').textContent=route.name;$('tour-subtitle').textContent=route.source+' → '+destinations[destinationOf(route)].name;populateChapters();setTime(0);view.flyTo(poseAt(stateAt(state.schedule,0)),3.8);state.playing=play&&!reduced;syncPlay();}
function populateChapters(){const select=$('chapter-select'),tabs=$('chapter-tabs');select.replaceChildren();tabs.replaceChildren();for(const c of state.schedule.chapters){select.append(new Option(`${String(c.index+1).padStart(2,'0')} · ${c.short}`,String(c.index)));const b=document.createElement('button');b.type='button';b.className='chapter-tab';b.textContent=c.short;b.setAttribute('aria-label',`Chapter ${c.index+1}: ${c.title}`);b.dataset.chapter=c.index;b.onclick=()=>jumpChapter(c.index);tabs.append(b);}}
function chapterNarrative(s){const c=s.chapter,key=`${state.mode}-${c.index}-${s.travelling}`;if(key===state.chapterKey)return;state.chapterKey=key;$('story-kind').textContent=s.travelling?'TRAVELLING DOWNSTREAM':c.kind;$('story-title').textContent=s.travelling?`Onward to ${c.short}`:c.title;$('story-text').textContent=s.travelling?(state.mode==='overview'?'Move across the landscape to the next part of the story.':'Stay with the growing river trace. The camera follows the channel and will slow down at the next stop.'):c.text;$('chapter-select').value=String(c.index);for(const b of $('chapter-tabs').children){b.setAttribute('aria-current',+b.dataset.chapter===c.index?'step':'false');b.classList.toggle('passed',+b.dataset.chapter<c.index);}$('chapter-position').textContent=`${String(c.index+1).padStart(2,'0')} / ${String(state.schedule.chapters.length).padStart(2,'0')}`;$('previous').disabled=c.index===0;$('next').disabled=c.index===state.schedule.chapters.length-1;$('next-journeys').hidden=!(state.mode==='overview'&&c.final&&!s.travelling);
 if(state.mode==='overview')overviewHighlight(s.travelling?s.previous.group:c.group);else{view.clearLabels('active');view.clear('branch');view.branchReveal=null;view.addLabel(c.short,samplePath(state.metric,c.t).point,'source','active');if(c.branch&&!s.travelling&&branches[c.branch]){const branch=branches[c.branch];view.showBranch({...branch,path:[...branch.path.slice(0,-1),samplePath(state.metric,c.t).point]});view.addLabel(branch.name,branch.path[Math.floor(branch.path.length*.62)],'tributary','active');view.addLabel(state.river.id==='ganga'&&c.branch==='alaknanda'?'Bhagirathi':'Ganga',samplePath(state.metric,Math.max(0,c.t-.018)).point,'river','active');}}
}
function poseAt(s){if(state.mode==='overview'){const c=s.chapter,p=s.previous,a=view.geo(...p.center),b=view.geo(...c.center),point=s.travelling?a.map((v,i)=>mix(v,b[i],s.phase)):b,d=s.travelling?mix(p.distance,c.distance,s.phase):c.distance*(1-.035*s.phase),bearing=s.travelling?shortestAngle(p.bearing,c.bearing,s.phase):c.bearing+.07*s.phase;return view.shot(point,d,bearing);}const c=s.chapter;let point=samplePath(state.metric,s.t).point,distance=s.travelling?4.4:(c.distance||3.6)*(1-.12*s.phase),bearing=s.travelling?headingAt(state.metric,s.t)+Math.PI+.6:(c.bearing??headingAt(state.metric,s.t)+Math.PI+.6)+.16*ease(s.phase);if(s.travelling){const p=s.previous,enter=ease(clamp(s.phase/.25)),leave=ease(clamp((s.phase-.75)/.25));const from=(p.bearing??headingAt(state.metric,p.t)+Math.PI+.6)+.16,to=c.bearing??headingAt(state.metric,c.t)+Math.PI+.6;bearing=shortestAngle(shortestAngle(from,bearing,enter),to,leave);distance=mix(mix((p.distance||3.6)*.88,4.4,enter),c.distance||3.6,leave);}if(c.index===state.schedule.chapters.length-1&&!s.travelling&&s.phase>.60){const t=ease((s.phase-.60)/.40);point=point.map((v,i)=>mix(v,routeBounds.center[i],t));distance=mix(distance,routeBounds.distance,t);bearing=shortestAngle(bearing,.15,t);}return view.shot(point,distance,bearing);}
function setTime(seconds){if(!state.schedule)return;state.time=clamp(seconds,0,state.schedule.duration);const s=stateAt(state.schedule,state.time);chapterNarrative(s);$('progress').value=Math.round(state.time/state.schedule.duration*1000);$('phase-label').textContent=s.travelling?'Following the river':s.done?'Journey complete':state.playing?`At this stop · ${Math.max(0,Math.ceil(s.chapter.end-state.time))}s`:'Take a moment to explore';$('elapsed').textContent=`${formatTime(state.time)} / ${formatTime(state.schedule.duration)}`;if(state.mode==='river'){view.revealRoute(samplePath(state.metric,s.t),!s.travelling,s.phase);view.revealBranch(state.playing?s.phase:1);}if(!state.free)view.aim(poseAt(s));if(s.done){state.playing=false;syncPlay();$('phase-label').textContent='Journey complete · replay or choose another river';}}
function seekJourney(seconds){if(!state.schedule||!Number.isFinite(seconds)||seconds<0||seconds>state.schedule.duration+.001)throw new Error('Choose a time within this journey.');if(Math.abs(seconds-state.schedule.duration)<.001)seconds=state.schedule.duration;guide.reset();local.reset();state.playing=false;state.free=false;state.activityPaused=true;$('resume-camera').hidden=true;setTime(seconds);view.flyTo(poseAt(stateAt(state.schedule,state.time)),.6);syncPlay();}
function formatTime(seconds){return `${Math.floor(seconds/60)}:${String(Math.floor(seconds%60)).padStart(2,'0')}`;}
function jumpChapter(index){if(!Number.isInteger(index)||index<0||index>=state.schedule.chapters.length)throw new Error('Choose an available chapter.');guide.reset();local.reset();state.activityPaused=true;state.playing=false;state.free=false;$('resume-camera').hidden=true;setTime(state.schedule.chapters[index].arrival);view.flyTo(poseAt(stateAt(state.schedule,state.time)),2.6);syncPlay();}
function syncPlay(){const running=state.playing||((state.free||state.reading)&&!!local?.active&&!state.activityPaused);$('play').textContent=running?'Ⅱ':'▶';$('play').setAttribute('aria-label',running?'Pause guided journey':state.time>=state.schedule?.duration?'Replay guided journey':'Play guided journey');$('play-label').textContent=(state.free||state.reading)&&local?.active?(state.activityPaused?'Play activity':'Pause activity'):state.reading?'Continue journey':state.playing?'Pause':'Play journey';}
function pausePlayback(){state.playing=false;state.activityPaused=true;syncPlay();}
function startPlayback(){if(!state.schedule)return;state.reading=false;if(state.free&&local.active){state.activityPaused=false;syncPlay();return;}if(state.time>=state.schedule.duration-.001){local.reset();setTime(0);view.flyTo(poseAt(stateAt(state.schedule,0)),2.4);}if(state.free){state.free=false;local.resume();$('resume-camera').hidden=true;view.guided=true;view.flyTo(poseAt(stateAt(state.schedule,state.time)),1.5);}state.activityPaused=false;state.playing=true;syncPlay();}
function playPause(){if(!state.schedule)return;if(state.reading&&local.active){state.activityPaused=!state.activityPaused;syncPlay();return;}const running=state.playing||((state.free||state.reading)&&!!local?.active&&!state.activityPaused);if(running)pausePlayback();else startPlayback();}
function resumeCamera(){state.reading=false;state.free=false;state.activityPaused=false;state.playing=true;local.resume();view.guided=true;$('resume-camera').hidden=true;if(!local.active)view.flyTo(poseAt(stateAt(state.schedule,state.time)),1.4);syncPlay();}
function exploreLocal(){state.reading=false;state.free=true;state.playing=false;state.activityPaused=false;$('resume-camera').hidden=true;syncPlay();}
function setSpeed(speed){if(!playbackSpeeds.includes(speed))throw new Error('Choose 0.5, 1, 1.5, 2 or 3 times speed.');state.speed=speed;$('journey-speed').value=String(speed);}
function snapshot(){const s=state.schedule?stateAt(state.schedule,state.time):null;return{mode:state.mode,river:state.river?.id||null,destination:state.destination,local:local?.snapshot(),playing:state.playing,speed:state.speed,reading:state.reading,guide:guide?.snapshot(),elapsed:+state.time.toFixed(2),duration:state.schedule?.duration||0,chapter:s?{index:s.chapter.index,title:s.chapter.title,kind:s.chapter.kind,travelling:s.travelling,routePosition:+s.t.toFixed(4)}:null,camera:view.snapshot(),renderMemory:{geometries:view.renderer.info.memory.geometries,textures:view.renderer.info.memory.textures},chapterCount:state.schedule?.chapters.length||0,chapters:state.schedule?.chapters.map(c=>({index:c.index,title:c.title,at:+(c.t||0).toFixed(4),arrival:c.arrival,end:c.end,scene:c.scene||null}))||[],revealedSegments:view.reveal?.geometry.drawRange.count||0,branchSegments:view.branchReveal?.parent?view.branchReveal.geometry.drawRange.count:0};}
function wireControls(){$('journey-speed').onchange=e=>setSpeed(Number(e.target.value));$('big-picture').onclick=()=>enterOverview(true);$('overview-nav').onclick=()=>enterOverview(true);$('journeys-nav').onclick=()=>{showExplorer();$('river').focus();};$('river').onchange=e=>{if(e.target.value)enterRiver(e.target.value,false);};document.querySelectorAll('[data-destination]').forEach(b=>b.onclick=()=>showExplorer(b.dataset.destination));document.querySelectorAll('[data-start-river]').forEach(b=>b.onclick=()=>enterRiver(b.dataset.startRiver,true));$('exit-tour').onclick=()=>showExplorer();$('overview').onclick=()=>showExplorer();$('play').onclick=playPause;$('play-label').onclick=playPause;$('chapter-select').onchange=e=>jumpChapter(+e.target.value);$('previous').onclick=()=>jumpChapter(stateAt(state.schedule,state.time).chapter.index-1);$('next').onclick=()=>jumpChapter(stateAt(state.schedule,state.time).chapter.index+1);$('progress').oninput=e=>{guide.reset();local.reset();state.activityPaused=true;state.playing=false;state.free=false;setTime(+e.target.value/1000*state.schedule.duration);view.flyTo(poseAt(stateAt(state.schedule,state.time)),.6);$('resume-camera').hidden=true;syncPlay();};$('resume-camera').onclick=resumeCamera;view.onExplore=()=>{if(state.mode==='explore'||local.active)return;state.free=true;state.playing=false;$('resume-camera').hidden=false;syncPlay();};$('tributaries').onchange=e=>view.networks[0].visible=e.target.checked;$('relief').onchange=e=>{view.world.scale.y=e.target.checked?1:.015;if(state.schedule)setTime(state.time);};for(const [id,factor] of [['zoom-in',.8],['zoom-out',1.2]])$(id).onclick=()=>{view.guided=false;view.flight=null;view.onExplore?.();view.camera.position.sub(view.controls.target).multiplyScalar(factor).add(view.controls.target);};$('about').onclick=()=>$('about-dialog').showModal();$('close-about').onclick=()=>$('about-dialog').close();document.addEventListener('keydown',e=>{if(e.code==='Space'&&state.mode!=='explore'&&e.target===document.body&&!$('about-dialog').open){e.preventDefault();playPause();}});}
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController(),register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'select_river',description:'Open a named river’s cinematic chapter tour, fly to its source, and optionally play the guided journey.',inputSchema:{type:'object',properties:{river:{type:'string',enum:['all',...routes.map(r=>r.id)]},start:{type:'boolean'}},required:['river'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['all',...routes.map(r=>r.id)].includes(input.river)||('start'in input&&typeof input.start!=='boolean'))throw new Error('Choose a valid river and boolean start value.');input.river==='all'?showExplorer():enterRiver(input.river,input.start||false);return snapshot();}});
 register({name:'control_guided_journey',description:'Start the India drainage overview, jump to a chapter, seek to presentation seconds, play, pause, or restore the guided camera. Chapter indices start at zero.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['overview','chapter','seek','play','pause','resume_camera']},chapter:{type:'integer',minimum:0},seconds:{type:'number',minimum:0}},required:['action'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['overview','chapter','seek','play','pause','resume_camera'].includes(input.action))throw new Error('Choose an available journey action.');if(input.action==='overview')enterOverview(true);else{if(!state.schedule)throw new Error('Open a journey first.');if(input.action==='chapter')jumpChapter(input.chapter);if(input.action==='seek')seekJourney(input.seconds);if(input.action==='play')startPlayback();if(input.action==='pause')pausePlayback();if(input.action==='resume_camera')resumeCamera();}return snapshot();}});
 register({name:'control_local_scene',description:'Explore a point in the active Ganga miniature, choose above or atlas viewpoint, or return to the guided journey. Read journey state for available point IDs.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['poi','viewpoint','return']},value:{type:'string'}},required:['action'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['poi','viewpoint','return'].includes(input.action))throw new Error('Choose a scene action.');local.interact(input.action,input.value);return snapshot();}});
 register({name:'set_journey_speed',description:'Set the playback speed without changing the current place or pause state.',inputSchema:{type:'object',properties:{speed:{type:'number',enum:playbackSpeeds}},required:['speed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){setSpeed(input?.speed);return snapshot();}});
 register({name:'control_journey_guide',description:'Hold the journey to read while local activity continues, browse guide notes, or continue the tour.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['hold','previous','next','continue']}},required:['action'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!guide.notes.length||state.free)throw new Error('Open a guided Ganga chapter first.');if(input.action==='hold')guide.hold();else if(input.action==='previous')guide.browse(-1);else if(input.action==='next')guide.browse(1);else if(input.action==='continue')startPlayback();else throw new Error('Choose a guide action.');guide.sync(stateAt(state.schedule,state.time),state.river?.id,!!local.active,state.free);return snapshot();}});
 register({name:'read_journey_state',description:'Read the current river, chapter, revealed route, playback status and camera position.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return snapshot();}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
async function init(){view=new TerrainView($('scene'));local=new LocalScenes(view,{explore:exploreLocal,resume:resumeCamera,atlas(){view.guided=true;$('resume-camera').hidden=false;const s=stateAt(state.schedule,state.time);view.flyTo(state.river?.id==='ganga'&&s.chapter.scene==='estuary'?view.shot(routeBounds.center,routeBounds.distance,.15):poseAt(s),2);}});const get=async(path,binary=false)=>{const r=await fetch(path);if(!r.ok)throw new Error(`Unable to load ${path}`);return binary?r.arrayBuffer():r.json();};const data=await Promise.all([get('./data/metadata.json'),get('./data/elevation.bin',true),get('./data/land.json'),get('./data/routes.json'),get('./data/branches.json'),...[0,1,2].map(i=>get(`./data/network-${i}.bin`,true))]);[meta,,,routes,branches]=data;view.load(meta,new Float32Array(data[1]),data[2],data.slice(5).map(a=>new Float32Array(a)));for(const r of routes){const mesh=view.ribbon(r.path,destinations[destinationOf(r)].color,.013,.8);view.group('overview').add(mesh);const metric=pathMetric(r.path),arrows=[.28,.60,.85].map(t=>{const p=samplePath(metric,t).point,q=samplePath(metric,t+.004).point,a=view.directionArrow(p,q.map((v,i)=>v-p[i]),destinations[destinationOf(r)].color);view.group('overview').add(a);return a;});overviewLines.push({route:r,mesh,arrows});}$('coverage').textContent=`${meta.indiaReaches.toLocaleString('en-IN')} mapped river sections across India. Coloured routes show 19 featured journeys.`;$('data-details').innerHTML=`<p>The background includes ${meta.indiaReaches.toLocaleString('en-IN')} HydroRIVERS reaches intersecting the Natural Earth India boundary, with connected basins retained in the regional view. A reach is a river section, not a separately named river.</p><p>HydroRIVERS maps channels with catchment ≥10 km² or average flow ≥0.1 m³/s. Smaller streams, canals and many distributaries are missing. Its single downstream connection cannot reproduce every delta split.</p><p>Named journeys follow mapped downstream links. Source regions and chapter locations are approximate at this scale. The Ganga tour follows the Padma route, not the Bhagirathi–Hooghly branch. Mapped outlets may lie at the upstream edge of an estuary rather than the open sea.</p><p>The Devprayag and Prayagraj tributary approaches are extracted from the same connected river dataset. Terrain is sampled and exaggerated about 44×; fine river geometry may not align perfectly with this coarse terrain in close views.</p><p><a href="./data/hydro-license.pdf">HydroSHEDS terms</a> · <a href="./data/HydroRIVERS_TechDoc_v10.pdf">Dataset documentation</a></p>`;guide=new JourneyGuide(state,startPlayback);wireControls();$('loading').remove();document.querySelectorAll('[data-ready]').forEach(b=>b.disabled=false);$('atlas').setAttribute('aria-busy','false');showExplorer();registerTools();window.riverAtlas={getState:snapshot,selectRiver:enterRiver,start:playPause};requestAnimationFrame(frame);}
function frame(time){const dt=Math.min(.1,(time-lastTime)/1000||0);lastTime=time;if(state.schedule){if(state.playing&&!state.reading&&!view.flight&&!document.hidden)state.time+=dt*state.speed;setTime(state.time);}local.sync(state,state.schedule?stateAt(state.schedule,state.time):null,dt);guide.sync(state.schedule?stateAt(state.schedule,state.time):null,state.river?.id,!!local.active,state.free);view.update(dt*(state.playing?state.speed:1));syncPlay();requestAnimationFrame(frame);}
init().catch(error=>{console.error(error);$('loading').textContent='The 3D view could not load. Please reload, and check that WebGL is enabled.';});
